def candy(ratings):
    n = len(ratings)
    candies = [1] * n
    for i in range(1, n):              # left neighbour rule
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1
    for i in range(n - 2, -1, -1):     # right neighbour rule, keep both
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)
    return sum(candies)

