def can_complete_circuit(gas, cost):
    n = len(gas)
    for start in range(n):             # simulate the trip from every station
        tank = 0
        for k in range(n):
            i = (start + k) % n
            tank += gas[i] - cost[i]
            if tank < 0:
                break
        else:
            return start
    return -1

