import heapq
from collections import Counter

def is_n_straight_hand(hand, group_size):
    if len(hand) % group_size:
        return False
    count = Counter(hand)
    heap = list(count)                 # distinct card values, smallest first
    heapq.heapify(heap)
    while heap:
        first = heap[0]                # smallest card must start a group
        for card in range(first, first + group_size):
            if count[card] == 0:
                return False
            count[card] -= 1
            if count[card] == 0:
                if card != heap[0]:
                    return False       # a smaller card would be left stranded
                heapq.heappop(heap)
    return True

