from collections import Counter

def is_n_straight_hand(hand, group_size):
    count = Counter(hand)
    for card in sorted(count):         # the smallest remaining card starts runs
        need = count[card]
        if need:
            for nxt in range(card, card + group_size):
                if count[nxt] < need:
                    return False
                count[nxt] -= need     # start `need` runs at once
    return True

