def jump(nums):
    n = len(nums)
    dp = [0] + [float('inf')] * (n - 1)   # dp[i]: fewest jumps to reach i
    for i in range(n):
        for j in range(i + 1, min(n, i + nums[i] + 1)):
            dp[j] = min(dp[j], dp[i] + 1)
    return dp[-1]

